import { OceanEngine } from "ascii-sharks";

const canvas = document.querySelector("canvas");
const engine = new OceanEngine(canvas, [
  { kind: "hammerhead", size: 1 },
  { kind: "thresher", size: 0.78 },
  { kind: "mako", size: 0.64 },
  { kind: "nurse", size: 0.5 },
]);

// engine.destroy() cleans up the loop, resize and pointer listeners.

import { OceanEngine } from 'ascii-sharks'
import type { SharkSpec } from 'ascii-sharks/world'

/* Tags: great hammerhead shark ascii animation, ascii shark animation, canvas ocean, boids fish simulation */

// A lone ASCII great hammerhead shark leads a boids fish school on canvas.
const SHARKS: SharkSpec[] = [{ kind: 'greathammer', size: 1 }]

const canvas = document.getElementById('ocean') as HTMLCanvasElement
const engine = new OceanEngine(canvas, SHARKS)
// engine.destroy() when the demo unmounts

